/* 사케 카드 — 앱 로직.
   도감(catalog.json)은 읽기 전용, 내 컬렉션과 노트는 localStorage.
   서버 없이 각자 브라우저에 남는다. */
(function(){
'use strict';
var K_MINE='sake.mine.v1', K_NOTE='sake.note.v1', K_BACK='sake.backup.v1';
var AX=[['華やか','화려함'],['芳醇','풍부함'],['重厚','묵직함'],['穏やか','부드러움'],['ドライ','드라이'],['軽快','가벼움']];
var TAGS=[['酸味','산미'],['辛口','드라이'],['旨味','감칠맛'],['フルーティ','과일향'],['スッキリ','깔끔'],
          ['しっかり','묵직'],['甘味','단맛'],['穀物','곡물향'],['苦味','쓴맛'],['コク','바디감'],
          ['バランス','균형'],['さっぱり','산뜻'],['ほのか','은은'],['キレ','끝맛']];
var AGAIN=['좋았다','괜찮다','아쉬웠다'];
var TEMPS=[['雪冷え','유키비에 5℃'],['花冷え','하나비에 10℃'],['常温','상온 20℃'],
           ['ぬる燗','누루칸 40℃'],['熱燗','아츠칸 50℃']];
var PREM=['十四代','而今','飛露喜','新政','黒龍','磯自慢','勝駒','花陽浴','射美'];
var CAT=[], MINE={}, NOTE={}, dexN=60, curId=null;

function load(k,d){try{return JSON.parse(localStorage.getItem(k))||d}catch(e){return d}}
/* 노트는 [{at,mine,tags,temp,memo,again}, ...] 로 쌓인다. 같은 술을 다시 마시면
   덮어쓰지 않고 붙는다 — 사케는 온도·상태로 인상이 달라져서 이전 기록이 정보다.
   초기 버전은 객체 하나였으므로 읽을 때 배열로 올린다. */
function logsOf(id){
  var n=NOTE[id]; if(!n)return [];
  if(Array.isArray(n))return n;
  return [n];
}
function lastLog(id){var l=logsOf(id);return l.length?l[l.length-1]:null}
/* 카드 한 장은 **제품 한 병**이다. 도감(catalog.json)은 브랜드 단위라
   한 브랜드에 여러 제품이 걸린다 — 브랜드로 키를 잡으면 칸키쿠 14병이 한 장으로
   뭉쳐 컬렉션이 무너진다(2026-09-16 실측: 135병을 담았는데 카드 71장).
   그래서 카드 키는 `<도감id>#<제품명>` 이고, 제품명이 없으면 도감 id 그대로다. */
function baseOf(id){var i=String(id).indexOf('#');return i<0?String(id):String(id).slice(0,i)}
function prodOf(id){var i=String(id).indexOf('#');return i<0?'':String(id).slice(i+1)}
function catOf(id){var b=baseOf(id);for(var i=0;i<CAT.length;i++)if(CAT[i].id===b)return CAT[i];return null}
/* 도감 카드(브랜드)에 「所持」를 붙일지 — 그 브랜드로 담은 병이 하나라도 있으면 붙인다 */
function ownedBrand(bid){for(var k in MINE)if(baseOf(k)===bid)return true;return false}
function notedBrand(bid){for(var k in NOTE)if(baseOf(k)===bid)return true;return false}
function variantsOf(bid){var o=[];for(var k in MINE)if(baseOf(k)===bid)o.push(k);return o}
/* 카드 한 장 = 도감 정보 + 내가 담은 병의 제품명 */
/* 양조장 — 한국어 표기가 있으면 그쪽을 쓴다. 한자만 있으면 한국 사람이 못 읽는다. */
function brewOf(c){return c?(c.breweryKo||c.brewery||''):''}
/* 이름 한 줄 — 일본어 뒤에 아는 독음을 붙인다 */
function nameOf(c){
  if(!c)return '-';
  var y=(catOf(c.id)||{}).ko||'';
  return c.jp+(y?' '+y:'');
}
function cardOf(id){
  var c=catOf(id), m=MINE[id]||{}, pr=prodOf(id), o={};
  if(c)for(var k in c)o[k]=c[k];
  o.id=id;
  o.jp=c?c.jp:(m.jp||'?');
  /* 제품명을 모르는 병은 브랜드명이 제품명 자리에 들어와 있다(사진으로만 찾은 술).
     그대로 두면 같은 이름이 두 줄로 겹치므로 한국어 독음으로 바꾼다. */
  o.ko=pr||m.name||'';
  if(c&&o.ko===c.jp)o.ko='';
  /* 도감에 없는 술은 이름과 제품명이 같게 들어온다(「RETRO 레트로」). 그대로 두면
     카드에 같은 말이 두 줄로 겹친다 — 앞에 겹치는 만큼 떼어 낸다. */
  if(o.ko===o.jp)o.ko='';
  else if(o.jp&&o.ko.indexOf(o.jp)===0)o.ko=o.ko.slice(o.jp.length).trim();
  if(!o.ko&&c)o.ko=c.ko||'';
  o.area=o.area||''; o.brewery=o.brewery||'';
  if(!('f' in o))o.f=null;
  o.at=m.at||'';
  return o;
}
function save(k,v){try{localStorage.setItem(k,JSON.stringify(v))}catch(e){toast('저장 공간이 부족합니다')}}
function $(s){return document.querySelector(s)}
function $$(s){return [].slice.call(document.querySelectorAll(s))}
function esc(s){return String(s==null?'':s).replace(/[&<>"]/g,function(c){
  return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]})}
/* 조사 — 받침 유무로 고른다. 한글이 아니면(일본어·영문 검색어) 받침 없는 쪽을 쓴다. */
function josa(w,withBat,noBat){
  var c=String(w||'').trim().slice(-1);
  if(!c)return noBat;
  var code=c.charCodeAt(0);
  if(code>=0xac00&&code<=0xd7a3)return (code-0xac00)%28?withBat:noBat;
  return noBat;
}
function toast(m){var t=$('#toast');t.textContent=m;t.classList.add('on');
  clearTimeout(toast._t);toast._t=setTimeout(function(){t.classList.remove('on')},1800)}

/* ── 카드 ── */
/* 검은 카드 = 사케노와 랭킹 상위. 이름을 손으로 적어 두면 데이터가 갱신돼도 안 바뀐다. */
function isPrem(s){
  if(s.rank&&s.rank<=27)return true;
  for(var i=0;i<PREM.length;i++)if((s.jp||'').indexOf(PREM[i])>=0)return true;
  return false;
}
function hue(f){ /* 가벼움↔묵직함으로 밴드 색을 잡는다 */
  var light=f[5], rich=f[1];
  var t=Math.max(0,Math.min(1,(rich-light+1)/2));
  return Math.round(90 - t*70);
}
/* 카드 얼굴 — 맛 6축을 작게 그린다. 이게 없으면 카드 위쪽이 통째로 빈 공간이라
   카드를 모으는 앱인데 모을 맛이 안 난다(2026-09-16 지적).
   내가 그린 값이 있으면 그걸, 없으면 도감 평균을 흐리게 얹는다. */
function miniRadar(f,mine,dark){
  var C=50,R=34,s=[];
  function pt(i,v){var a=-Math.PI/2+i*Math.PI/3;return [C+Math.cos(a)*R*v,C+Math.sin(a)*R*v]}
  function poly(v){return v.map(function(x,i){return pt(i,Math.max(.06,x)).join(',')}).join(' ')}
  var web=dark?'rgba(201,168,106,.22)':'rgba(33,29,24,.13)';
  s.push('<polygon points="'+poly([1,1,1,1,1,1])+'" fill="none" stroke="'+web+'"/>');
  s.push('<polygon points="'+poly([.5,.5,.5,.5,.5,.5])+'" fill="none" stroke="'+web+'"/>');
  for(var i=0;i<6;i++){var p=pt(i,1);
    s.push('<line x1="'+C+'" y1="'+C+'" x2="'+p[0]+'" y2="'+p[1]+'" stroke="'+web+'"/>')}
  var col=dark?'#c9a86a':'var(--me)';
  if(mine){
    if(f)s.push('<polygon points="'+poly(f)+'" fill="none" stroke="'+web+'" stroke-dasharray="2 2"/>');
    s.push('<polygon points="'+poly(mine)+'" fill="'+col+'" fill-opacity="'+(dark?'.26':'.2')
      +'" stroke="'+col+'" stroke-width="1.6"/>');
  }else if(f){
    s.push('<polygon points="'+poly(f)+'" fill="'+col+'" fill-opacity="'+(dark?'.14':'.1')
      +'" stroke="'+col+'" stroke-opacity=".55" stroke-width="1.2"/>');
  }
  return '<svg class="mini" viewBox="0 0 100 100" aria-hidden="true">'+s.join('')+'</svg>';
}
/* ── 내 사진 ──
   카드에 내가 찍은 병 사진을 붙인다. localStorage 는 5MB 라 사진 몇 장에 꽉 차므로
   IndexedDB 에 넣는다. 저장 전에 긴 변 900px·JPEG 로 줄여 장당 100KB 안쪽으로 만든다. */
var PIC={}, picDB=null, SHOT={};
function picOf(id){return PIC[id]||(SHOT[id]?'./photos/'+SHOT[id]:'')}
function openPicDB(){
  return new Promise(function(res){
    if(picDB)return res(picDB);
    var rq=indexedDB.open('sake-pics',1);
    rq.onupgradeneeded=function(){rq.result.createObjectStore('pics')};
    rq.onsuccess=function(){picDB=rq.result;res(picDB)};
    rq.onerror=function(){res(null)};
  });
}
function picPut(id,blobUrl){
  return openPicDB().then(function(db){
    if(!db)return;
    return new Promise(function(res){
      var tx=db.transaction('pics','readwrite');
      tx.objectStore('pics').put(blobUrl,id);
      tx.oncomplete=function(){PIC[id]=blobUrl;res()};
      tx.onerror=function(){res()};
    });
  });
}
function picDel(id){
  delete PIC[id];
  return openPicDB().then(function(db){
    if(!db)return;
    var tx=db.transaction('pics','readwrite');
    tx.objectStore('pics').delete(id);
  });
}
function picLoadAll(){
  return openPicDB().then(function(db){
    if(!db)return;
    return new Promise(function(res){
      var tx=db.transaction('pics','readonly'), st=tx.objectStore('pics');
      var ks=st.getAllKeys(), vs=st.getAll();
      tx.oncomplete=function(){
        (ks.result||[]).forEach(function(k,i){PIC[k]=(vs.result||[])[i]});
        res();
      };
      tx.onerror=function(){res()};
    });
  });
}
/* ── 배경 지우기 ──
   찍은 사진을 그대로 얹으면 바 조명과 잡동사니가 같이 들어와 카드가 지저분해진다.
   병만 남기려면 사람 손이 필요한데, 브라우저에서 바로 해 준다.

   U²-Net(u2netp, 4.4MB) 을 onnxruntime-web 으로 돌린다. 처음 한 번만 받고 그 뒤로는
   캐시에서 읽는다. 실패하면(구형 기기·메모리 부족) 원본을 그대로 쓴다 — 사진을 넣는
   일 자체가 막히면 안 된다. */
var ORT_URL='https://cdn.jsdelivr.net/npm/onnxruntime-web@1.19.2/dist/ort.min.js';
var cutSession=null, cutLoading=null;
function loadCutter(){
  if(cutSession)return Promise.resolve(cutSession);
  if(cutLoading)return cutLoading;
  cutLoading=new Promise(function(res,rej){
    var sc=document.createElement('script');
    sc.src=ORT_URL; sc.onload=res; sc.onerror=rej;
    document.head.appendChild(sc);
  }).then(function(){
    window.ort.env.wasm.wasmPaths='https://cdn.jsdelivr.net/npm/onnxruntime-web@1.19.2/dist/';
    return window.ort.InferenceSession.create('./u2netp.onnx',
      {executionProviders:['wasm'],graphOptimizationLevel:'all'});
  }).then(function(se){cutSession=se;return se});
  return cutLoading;
}
/* 이미지 → 알파가 들어간 캔버스. 못 하면 null */
function cutout(img){
  var N=320;
  return loadCutter().then(function(se){
    var c=document.createElement('canvas'); c.width=N; c.height=N;
    var x=c.getContext('2d'); x.drawImage(img,0,0,N,N);
    var d=x.getImageData(0,0,N,N).data;
    /* rembg 와 같은 전처리 — 최댓값으로 나눈 뒤 ImageNet 평균·편차로 정규화 */
    var mx=0; for(var i=0;i<d.length;i+=4){
      if(d[i]>mx)mx=d[i]; if(d[i+1]>mx)mx=d[i+1]; if(d[i+2]>mx)mx=d[i+2]}
    mx=mx||255;
    var M=[0.485,0.456,0.406], S=[0.229,0.224,0.225];
    var t=new Float32Array(3*N*N);
    for(var p=0,j=0;p<N*N;p++,j+=4){
      t[p]        =((d[j]  /mx)-M[0])/S[0];
      t[N*N+p]    =((d[j+1]/mx)-M[1])/S[1];
      t[2*N*N+p]  =((d[j+2]/mx)-M[2])/S[2];
    }
    var feed={}; feed[se.inputNames[0]]=new window.ort.Tensor('float32',t,[1,3,N,N]);
    return se.run(feed);
  }).then(function(out){
    var key=Object.keys(out)[0], m=out[key].data;
    var lo=Infinity, hi=-Infinity;
    for(var i=0;i<m.length;i++){if(m[i]<lo)lo=m[i]; if(m[i]>hi)hi=m[i]}
    var rng=(hi-lo)||1;
    /* 마스크를 원본 크기로 되돌려 알파로 쓴다 */
    var mc=document.createElement('canvas'); mc.width=N; mc.height=N;
    var mx2=mc.getContext('2d'), mi=mx2.createImageData(N,N);
    for(var p=0,j=0;p<N*N;p++,j+=4){
      var v=Math.round(((m[p]-lo)/rng)*255);
      mi.data[j]=mi.data[j+1]=mi.data[j+2]=255; mi.data[j+3]=v;
    }
    mx2.putImageData(mi,0,0);
    return mc;
  }).catch(function(){return null});
}
/* 파일 → 긴 변 900px JPEG data URL. 원본을 그대로 넣으면 한 장에 5MB 도 나온다. */
function shrink(file,cut){
  return new Promise(function(res,rej){
    var fr=new FileReader();
    fr.onload=function(){
      var img=new Image();
      img.onload=function(){
        var M=900, w=img.width, h=img.height;
        var sc=Math.min(1,M/Math.max(w,h));
        var c=document.createElement('canvas');
        c.width=Math.round(w*sc); c.height=Math.round(h*sc);
        var x=c.getContext('2d');
        x.drawImage(img,0,0,c.width,c.height);
        if(!cut)return res(c.toDataURL('image/jpeg',0.72));
        cutout(img).then(function(mask){
          if(!mask)return res(c.toDataURL('image/jpeg',0.72));   /* 못 하면 원본 */
          /* 마스크를 알파로 씌우고, 남은 것만 잘라 낸다 */
          x.globalCompositeOperation='destination-in';
          x.drawImage(mask,0,0,c.width,c.height);
          x.globalCompositeOperation='source-over';
          var box=alphaBox(c);
          var o=document.createElement('canvas');
          o.width=box[2]; o.height=box[3];
          var ox=o.getContext('2d');
          ox.fillStyle='#f4f1e9'; ox.fillRect(0,0,o.width,o.height);  /* 카드 바탕색 */
          ox.drawImage(c,box[0],box[1],box[2],box[3],0,0,box[2],box[3]);
          res(o.toDataURL('image/jpeg',0.76));
        });
      };
      img.onerror=rej; img.src=fr.result;
    };
    fr.onerror=rej; fr.readAsDataURL(file);
  });
}
/* 알파가 남아 있는 영역의 사각 범위 — 배경을 지우고 나면 여백이 많이 남는다 */
function alphaBox(c){
  var d=c.getContext('2d').getImageData(0,0,c.width,c.height).data;
  var x0=c.width,y0=c.height,x1=0,y1=0, found=false;
  for(var y=0;y<c.height;y+=2)for(var x=0;x<c.width;x+=2){
    if(d[(y*c.width+x)*4+3]>28){
      found=true;
      if(x<x0)x0=x; if(x>x1)x1=x; if(y<y0)y0=y; if(y>y1)y1=y;
    }
  }
  if(!found)return [0,0,c.width,c.height];
  var pad=8;
  x0=Math.max(0,x0-pad); y0=Math.max(0,y0-pad);
  x1=Math.min(c.width,x1+pad); y1=Math.min(c.height,y1+pad);
  return [x0,y0,Math.max(1,x1-x0),Math.max(1,y1-y0)];
}
/* 사케 병 — 사진을 쓸 수 없으니(라벨은 양조장 저작물) 병을 그린다.
   유리색은 맛 색을 따라가고, 라벨에는 이름 첫 글자를 얹는다. */
function bottleSVG(s,f,dark){
  var h=hue(f), glass='hsl('+h+',34%,'+(dark?28:62)+'%)';
  var ch=(s.jp||'酒').replace(/[^\u3040-\u30ff\u4e00-\u9fafA-Za-z]/g,'').slice(0,1)||'酒';
  var cap=dark?'#c9a86a':'#8a7645';
  var lab=dark?'#e8e0cf':'#fbf8f0', labInk=dark?'#2a251c':'#332d22';
  return '<svg class="bottle" viewBox="0 0 40 100" aria-hidden="true">'
    +'<path d="M16 8 L24 8 L24 27 C24 31 35 33 35 45 L35 93 Q35 97 31 97 L9 97 Q5 97 5 93 L5 45 C5 33 16 31 16 27 Z" '
      +'fill="'+glass+'" fill-opacity="'+(dark?'.85':'.55')+'" stroke="hsl('+h+',30%,'+(dark?38:46)+'%)" stroke-opacity=".7" stroke-width="1"/>'
    +'<rect x="15" y="3" width="10" height="7" rx="1.6" fill="'+cap+'" fill-opacity=".9"/>'
    +'<rect x="7" y="52" width="26" height="30" rx="2" fill="'+lab+'" fill-opacity="'+(dark?'.92':'.95')+'"/>'
    +'<text x="20" y="73" text-anchor="middle" font-size="17" fill="'+labInk+'" '
      +'font-family="Yu Mincho,Hiragino Mincho ProN,serif">'+esc(ch)+'</text>'
    +'<rect x="7" y="52" width="26" height="30" rx="2" fill="none" stroke="'+labInk+'" stroke-opacity=".18"/>'
    /* 유리 하이라이트 */
    +'<path d="M10 46 L10 92" stroke="#fff" stroke-opacity="'+(dark?'.12':'.45')+'" stroke-width="2.4" stroke-linecap="round"/>'
    +'</svg>';
}
function cardHTML(s,opts){
  opts=opts||{};
  var prem=isPrem(s), mine=!!MINE[s.id]||ownedBrand(s.id), noted=!!NOTE[s.id]||notedBrand(s.id);
  var f=s.f||[.5,.5,.5,.5,.5,.5];
  var log=lastLog(s.id);
  var pic=picOf(s.id);
  var front='<div class="face front'+(pic?' haspic':'')+'">'
    +'<div class="band" style="background:hsl('+hue(f)+',42%,56%)"></div>'
    +(pic?'<img class="pic" src="'+pic+'" alt="">':bottleSVG(s,f,false))
    +'<div class="glyph" title="'+(s.t!=null?esc(AX[s.t][1]):'')+'">'
    +(s.t!=null?AX[s.t][0].charAt(0):'酒')+'</div>'
    +(noted?'<div class="noted">筆</div>':'')
    +'<div class="jp'+(s.jp.length>=7?' xs':(s.jp.length>=5?' sm':''))+'">'+esc(s.jp)+'</div>'
    +'<div class="ko">'+esc(s.ko||brewOf(s))+'</div>'
    +'<div class="foot"><span>'+esc(s.area||'')+'</span>'
    +'<span>'+(s.rank?'<i class="rk">인기 '+s.rank+'위</i>':'')+(mine?'담음':'')+'</span></div>'
    +(s.no?'<div class="no">No.'+s.no+'</div>':'')
    +'</div>';
  /* 뒷면 — 맛과 내 기록. 탭 한 번에 나오는 게 재미다. */
  var rows=[];
  if(s.t!=null)rows.push(['맛 타입',AX[s.t][1]]);
  if(log){
    if(typeof log.temp==='number')rows.push(['마신 온도',TEMPS[log.temp][1]]);
    if((log.tags||[]).length)rows.push(['맛·향',log.tags.slice(0,3).map(tagKo).join(' · ')]);
    if(log.at)rows.push(['마신 날',(log.at||'').slice(0,10).replace(/-/g,'.')]);
  }else{
    if(brewOf(s))rows.push(['양조장',brewOf(s)]);
    if(s.area)rows.push(['지역',s.area]);
    if(!mine)rows.push(['','아직 안 담은 술']);
  }
  var back='<div class="face back">'
    +'<div class="band" style="background:hsl('+hue(f)+',42%,56%)"></div>'
    +'<div class="glyph">'+(s.t!=null?AX[s.t][0].charAt(0):'酒')+'</div>'
    +'<div class="bk-t">'+esc(s.jp)+(s.no?' <span style="opacity:.6">No.'+s.no+'</span>':'')+'</div>'
    +miniRadar(s.f,log&&log.mine,false)
    +'<div style="margin-top:52%">'
    + rows.map(function(r){
        return '<div class="bk-r"><span>'+esc(r[0])+'</span><b>'+esc(r[1])+'</b></div>'}).join('')
    + (log&&log.memo?'<div class="bk-memo">'+esc(log.memo)+'</div>':'')
    +'</div>'
    +'<div class="bk-btn" data-open-sheet="'+esc(s.id)+'">'+(mine?'열기':'담기')+'</div>'
    +'</div>';
  return '<div class="c'+(prem?' prem':'')+(opts.locked&&!mine?' locked':'')+'" data-id="'+esc(s.id)+'">'
    +'<div class="inner">'+front+back+'</div></div>';
}
/* 정렬 — 지역순은 「어느 지방 술인지」로, 맛순은 같은 성격끼리 모아 본다.
   Vivino 의 셀러가 포도·스타일로 갈라 보여 주는 것과 같은 축이다. */
function sortList(out,mode){
  if(mode==='jp')out.sort(function(a,b){return (a.jp||'').localeCompare(b.jp||'','ja')});
  else if(mode==='area')out.sort(function(a,b){
    return (a.area||'힣').localeCompare(b.area||'힣','ko')||(a.no||0)-(b.no||0)});
  else if(mode==='taste')out.sort(function(a,b){
    var ta=(a.t==null?9:a.t), tb=(b.t==null?9:b.t);
    return ta-tb||(a.no||0)-(b.no||0)});
  else if(mode==='new')out.sort(function(a,b){return (b.at||'').localeCompare(a.at||'')});
  else out.sort(function(a,b){return (a.no||9999)-(b.no||9999)});
  return out;
}
/* ── 도감 ── */
var dexFilter='all', dexTaste=-1;
function dexList(){
  var q=($('#q').value||'').trim().toLowerCase();
  var out=CAT.filter(function(s){
    if(dexFilter==='mine'&&!ownedBrand(s.id))return false;
    if(dexFilter==='new'&&ownedBrand(s.id))return false;
    if(dexTaste>=0&&s.t!==dexTaste)return false;
    if(!q)return true;
    return (s.jp+' '+(s.ko||'')+' '+(s.area||'')+' '+(s.brewery||'')+' '+(s.breweryKo||''))
      .toLowerCase().indexOf(q)>=0;
  });
  sortList(out,$('#sort').value);
  return out;
}
function renderDex(){
  var list=dexList(), shown=list.slice(0,dexN);
  $('#dex-grid').innerHTML=shown.map(function(s){return cardHTML(s,{locked:true})}).join('');
  $('#dex-count').textContent=list.length+'종'+(list.length>shown.length?' 중 '+shown.length+'종 표시':'');
  $('#dex-more').hidden=list.length<=shown.length;
  var none=$('#dex-none'); if(none){
    var q=($('#q').value||'').trim();
    none.querySelector('h3').textContent = list.length===0 && q
      ? '\u300c'+q+'\u300d'+josa(q,'\uc744','\ub97c')+' \ucc3e\uc9c0 \ubabb\ud588\uc2b5\ub2c8\ub2e4'
      : '\ucc3e\ub294 \uc220\uc774 \uc5c6\ub098\uc694?';
  }
}
/* ── 내 카드 ── */
var mineFilter='all';
function mineList(){
  var q=($('#mq').value||'').trim().toLowerCase();
  var out=Object.keys(MINE).map(cardOf);
  if(mineFilter==='noted')out=out.filter(function(s){return NOTE[s.id]});
  if(mineFilter==='blank')out=out.filter(function(s){return !NOTE[s.id]});
  if(q)out=out.filter(function(s){
    return (s.jp+' '+(s.ko||'')+' '+(s.area||'')+' '+(s.brewery||'')+' '+(s.breweryKo||''))
      .toLowerCase().indexOf(q)>=0});
  sortList(out,$('#msort').value);
  return out;
}
function renderMine(){
  var list=mineList(), has=Object.keys(MINE).length>0;
  var q=($('#mq').value||'').trim();
  /* 담은 카드는 있는데 검색·필터로 0건이면 빈 화면만 남아 고장처럼 보인다 */
  $('#mine-grid').innerHTML = list.length
    ? list.map(function(s){return cardHTML(s)}).join('')
    : (has ? '<p class="diff" style="grid-column:1/-1;text-align:center;padding:24px 8px">'
        +(q?'담은 카드 중에 <b>「'+esc(q)+'」</b>'+josa(q,'을','를')+' 찾지 못했습니다.'
           :'이 조건에 맞는 카드가 없습니다.')+'</p>' : '');
  $('#mine-count').textContent=list.length+'종';
  $('#mine-empty').hidden=has;
}
/* ── 홈 ── */
function renderHome(){
  var ids=Object.keys(MINE);
  $('#s-mine').textContent=ids.length;
  $('#s-note').textContent=Object.keys(NOTE).reduce(function(a,k){return a+logsOf(k).length},0);
  var brews={};ids.forEach(function(id){var s=catOf(id);
    if(s&&brewOf(s))brews[brewOf(s)]=1});
  $('#s-brew').textContent=Object.keys(brews).length;
  var bset={};ids.forEach(function(id){bset[baseOf(id)]=1});
  $('#s-brand').textContent=Object.keys(bset).length;
  $('#home-empty').hidden=ids.length>0;
  var gauge=$('#home-gauge');
  if(gauge){
    var brands={};ids.forEach(function(id){if(catOf(id))brands[baseOf(id)]=1});
    var nb=Object.keys(brands).length, na=Object.keys(areaCount()).length;
    gauge.hidden=!ids.length;
    if(ids.length)gauge.innerHTML=
       bar('도감', nb, CAT.length, nb+' / '+CAT.length+'종')
      +bar('지역', na, 47, na+' / 47곳');
  }
  /* 담기만 하고 노트를 안 쓴 카드가 쌓이면 어디서부터 손댈지가 막막하다.
     첫 장을 바로 열어 준다 — 저장하면 다음 장이 이어서 열린다. */
  var blank=$('#home-todo');
  if(blank){
    var left=blankIds(null).length;
    blank.hidden=!left;
    if(left)blank.innerHTML='<div style="display:flex;align-items:center;gap:12px">'
      +'<span style="flex:1;font-size:13.5px;word-break:keep-all">'
      +'아직 기록하지 않은 카드 <b>'+left+'장</b></span>'
      +'<button class="pri" id="go-blank" style="flex:0 0 auto;padding:9px 16px">채우기</button></div>';
  }
  var warn=$('#home-backup');
  if(warn){
    var b=sinceBackup(), pend=b.cards+b.notes;
    var show=ids.length>0&&(b.never?ids.length>=5:pend>=10);
    warn.hidden=!show;
    if(show)warn.innerHTML='<div style="display:flex;align-items:center;gap:12px">'
      +'<span style="flex:1;font-size:13px;word-break:keep-all">'
      +(b.never?'아직 <b>백업</b>한 적이 없습니다. 브라우저를 지우면 사라집니다'
               :'백업 이후 <b>'+pend+'건</b>이 쌓였습니다')
      +'</span><button id="go-backup" style="flex:0 0 auto;padding:8px 14px">백업</button></div>';
  }
  var recent=mineList().slice(0,6);
  $('#home-recent').innerHTML = recent.length
    ? '<p class="count" style="margin-top:18px">최근 담은 카드</p><div class="grid">'
      +recent.map(function(s){return cardHTML(s)}).join('')+'</div>' : '';
}
/* 담아만 두고 노트를 안 쓴 카드. 세정님처럼 135장을 먼저 담아 둔 경우
   한 장씩 찾아 여는 게 일이라, 저장하고 바로 다음 장으로 넘어갈 수 있게 한다. */
function blankIds(exceptId){
  return mineList().filter(function(s){
    return s.id!==exceptId && !logsOf(s.id).length;
  }).map(function(s){return s.id});
}
function blankLeft(id){return blankIds(id).length}
function nextBlank(id){var b=blankIds(id);return b.length?b[0]:null}
/* 마신 술의 지역 분포. 사케는 지역색이 뚜렷해서 「어디를 마셨나」가 곧 취향의 지도다.
   도감에 없는 술(own:)은 지역을 모르므로 세지 않는다 — 없는 값을 채우지 않는다. */
function areaCount(){
  var o={};
  Object.keys(MINE).forEach(function(id){
    var s=catOf(id); if(!s||!s.area)return;
    o[s.area]=(o[s.area]||0)+1;
  });
  return o;
}
/* 얼마나 모았나 — 한 줄짜리 막대 */
function bar(label,v,max,right){
  var pct=max?Math.min(100,v/max*100):0;
  return '<div style="display:flex;align-items:center;gap:9px;margin:7px 0">'
    +'<span style="flex:0 0 32px;font-size:11.5px;color:var(--ink3)">'+label+'</span>'
    +'<span style="flex:1;height:8px;background:var(--hair);border-radius:4px;overflow:hidden">'
    +'<span style="display:block;height:100%;width:'+(pct<1.2?1.2:pct)+'%;background:var(--me)"></span></span>'
    +'<span style="flex:0 0 76px;text-align:right;font-size:11px;color:var(--ink3)">'+esc(right)+'</span>'
    +'</div>';
}
/* 일본 지도 — 마신 지역을 칠한다. 지형을 그리지 않고 현청 좌표에 점을 찍는다.
   점만 찍어도 열도 모양이 나오고, 파일이 무거워지지 않는다. */
var GEO={"홋카이도":[43.1,141.3],"아오모리현":[40.8,140.7],"이와테현":[39.7,141.2],"미야기현":[38.3,140.9],"아키타현":[39.7,140.1],"야마가타현":[38.2,140.4],"후쿠시마현":[37.8,140.5],"이바라키현":[36.3,140.4],"도치기현":[36.6,139.9],"군마현":[36.4,139.1],"사이타마현":[35.9,139.6],"지바현":[35.6,140.1],"도쿄도":[35.7,139.7],"가나가와현":[35.4,139.6],"니가타현":[37.9,139.0],"도야마현":[36.7,137.2],"이시카와현":[36.6,136.6],"후쿠이현":[36.1,136.2],"야마나시현":[35.7,138.6],"나가노현":[36.7,138.2],"기후현":[35.4,136.7],"시즈오카현":[35.0,138.4],"아이치현":[35.2,136.9],"미에현":[34.7,136.5],"시가현":[35.0,135.9],"교토부":[35.0,135.8],"오사카부":[34.7,135.5],"효고현":[34.7,135.2],"나라현":[34.7,135.8],"와카야마현":[34.2,135.2],"돗토리현":[35.5,134.2],"시마네현":[35.5,133.1],"오카야마현":[34.7,133.9],"히로시마현":[34.4,132.5],"야마구치현":[34.2,131.5],"도쿠시마현":[34.1,134.6],"가가와현":[34.3,134.0],"에히메현":[33.8,132.8],"고치현":[33.6,133.5],"후쿠오카현":[33.6,130.4],"사가현":[33.2,130.3],"나가사키현":[32.7,129.9],"구마모토현":[32.8,130.7],"오이타현":[33.2,131.6],"미야자키현":[31.9,131.4],"가고시마현":[31.6,130.6],"오키나와현":[26.2,127.7]};
function badgeState(){
  var ids=Object.keys(MINE), n=noteCount();
  var brands={}, brews={}, temps={}, famous=0, own=0, maxBrand=0, types={};
  ids.forEach(function(id){
    var b=baseOf(id); brands[b]=(brands[b]||0)+1;
    if(brands[b]>maxBrand)maxBrand=brands[b];
    var c=catOf(id);
    if(c){ if(brewOf(c))brews[brewOf(c)]=1; if(c.rank&&c.rank<=27)famous++;
           if(c.t!=null)types[c.t]=1; }
    else own++;
  });
  Object.keys(NOTE).forEach(function(k){
    logsOf(k).forEach(function(l){if(typeof l.temp==='number')temps[l.temp]=1})});
  var areas=Object.keys(areaCount()).length;
  /* [이름, 단위, 현재값, 단계 문턱들] — 단계가 있으면 하나를 채워도 다음 칸이 남는다.
     Untappd 가 배지를 여러 단계로 두는 이유다(채운 칸 옆의 빈 칸이 다음을 당긴다). */
  return [
    ['병',     '장',   ids.length,               [1,10,50,100,200]],
    ['기록',   '건',   n,                        [1,10,50,100]],
    ['지역',   '곳',   areas,                    [5,10,24,47]],
    ['양조장', '곳',   Object.keys(brews).length,[5,20,50,100]],
    ['한 우물','병',   maxBrand,                 [3,5,10,20]],
    ['맛',     '타입', Object.keys(types).length,[3,6]],
    ['온도',   '가지', Object.keys(temps).length,[3,5]],
    ['이름난 술','종', famous,                   [1,10,27]],
    ['숨은 술','종',   own,                      [1,5,10]]
  ];
}
var LV=['Ⅰ','Ⅱ','Ⅲ','Ⅳ','Ⅴ'];
function renderBadges(){
  var box=$('#st-badge'); if(!box)return;
  var list=badgeState(), total=0, got=0;
  list.forEach(function(b){
    total+=b[3].length;
    b[3].forEach(function(th){if(b[2]>=th)got++});
  });
  box.innerHTML='<h3>배지 <span style="font-weight:400;color:var(--ink3)">'
      +got+' / '+total+'</span></h3>'
    +'<div class="bdgs">'
    + list.map(function(b){
        var name=b[0], unit=b[1], v=b[2], ths=b[3];
        var lv=0; ths.forEach(function(th){if(v>=th)lv++});
        var next=lv<ths.length?ths[lv]:null;
        return '<div class="bdg'+(lv?' on':'')+'">'
          +'<div class="bdg-h"><b>'+esc(name)+'</b>'
          +'<span class="bdg-lv">'+(lv?LV[lv-1]:'—')+'</span></div>'
          +'<div class="bdg-dots">'
          + ths.map(function(th,k){return '<i class="'+(k<lv?'f':'')+'"></i>'}).join('')
          +'</div>'
          +'<span class="bdg-s">'+(next? v+' / '+next+unit : '다 모았습니다')+'</span>'
          +'</div>'}).join('')
    +'</div>';
}
var MAP=null, mapTried=false;
/* 지도는 132KB 라 앱을 열 때마다 받으면 첫 화면이 늦는다 — 분석 탭에 들어올 때 받는다. */
function loadMap(){
  if(MAP||mapTried)return Promise.resolve(MAP);
  mapTried=true;
  return fetch('./japan.json',{cache:'force-cache'}).then(function(r){return r.json()})
    .then(function(d){MAP=d;return d}).catch(function(){return null});
}
function mapSVG(){
  var cnt=areaCount();
  if(!MAP){
    loadMap().then(function(d){if(d)renderArea()});
    return '<p class="diff" style="text-align:center;color:var(--ink3);margin:18px 0">지도를 불러오는 중…</p>';
  }
  var mx=1; for(var k in cnt)if(cnt[k]>mx)mx=cnt[k];
  var out=[];
  for(var name in MAP.p){
    var c=cnt[name]||0, fill;
    if(c){
      /* 많이 마신 곳일수록 진하게. 한 병이라도 마셨으면 확실히 보이게 바닥을 둔다. */
      var t=0.34+0.66*Math.sqrt(c/mx);
      fill='rgba(31,111,74,'+t.toFixed(2)+')';
    }else fill='var(--hair)';
    out.push('<path d="'+MAP.p[name]+'" fill="'+fill
      +'" stroke="var(--bg)" stroke-width=".7" data-area="'+esc(name)+'"><title>'
      +esc(name)+(c?' '+c+'병':'')+'</title></path>');
  }
  return '<svg viewBox="'+MAP.box.join(' ')+'" style="width:100%;max-width:290px;display:block;'
    +'margin:14px auto 2px">'+out.join('')+'</svg>'
    +'<p class="diff" style="text-align:center;font-size:11px;color:var(--ink3);margin-top:2px">'
    +'칠해진 곳이 마신 지역 · 진할수록 많이 마신 곳<br>'
    +'<span style="opacity:.75">오키나와는 규슈 옆으로 옮겨 그렸습니다</span></p>';
}
/* ── 분석 ── */
function renderStats(){
  var body=$('#stat-body'); if(!body)return;
  var has=Object.keys(MINE).length>0;
  var el=$('#stat-empty'); if(el)el.hidden=has;
  if(!has){body.innerHTML='';return}
  var notes=Object.keys(NOTE).reduce(function(a,k){return a+logsOf(k).length},0);
  body.innerHTML=
     '<div class="empty" style="text-align:left" id="st-sum"></div>'
    +'<div class="empty" style="text-align:left;margin-top:12px" id="st-badge"></div>'
    +'<div class="empty" style="text-align:left;margin-top:12px" id="st-brand"></div>'
    +'<div class="empty" style="text-align:left;margin-top:12px" id="st-mix"></div>'
    +'<div class="empty" style="text-align:left;margin-top:12px" id="me-area"></div>'
    +'<div class="empty" style="text-align:left;margin-top:12px" id="st-todo"></div>'
    +'<div class="empty" style="text-align:left;margin-top:12px" id="me-taste"></div>'
    +'<div class="empty" style="text-align:left;margin-top:12px" id="st-like"></div>';
  renderSum(notes); renderBadges(); renderBrandTop(); renderTasteMix();
  renderArea(); renderUnvisited();
  renderTaste(notes); renderLike();
}
/* 한눈 요약 — 몇 병을 어디까지 모았나 */
function renderSum(notes){
  var box=$('#st-sum'); if(!box)return;
  var ids=Object.keys(MINE), brews={}, brands={};
  ids.forEach(function(id){var c=catOf(id);
    if(c&&brewOf(c))brews[brewOf(c)]=1;
    brands[baseOf(id)]=1});
  box.innerHTML='<h3>모은 것</h3>'
    +'<p class="diff" style="margin-top:8px;font-size:14px;line-height:2">'
    +'병 <b>'+ids.length+'</b> · 브랜드 <b>'+Object.keys(brands).length+'</b>'
    +' · 양조장 <b>'+Object.keys(brews).length+'</b><br>'
    +'지역 <b>'+Object.keys(areaCount()).length+'</b>곳 · 기록 <b>'+notes+'</b>건</p>'
    + (notes? '' : '<p class="diff" style="color:var(--ink3)">한 잔 기록하면 아래에 취향이 그려집니다.</p>');
}
/* 많이 마신 브랜드 — 같은 이름이라도 병은 다르니 병 수로 센다 */
function renderBrandTop(){
  var box=$('#st-brand'); if(!box)return;
  var cnt={};
  Object.keys(MINE).forEach(function(id){var b=baseOf(id);cnt[b]=(cnt[b]||0)+1});
  var ks=Object.keys(cnt).sort(function(a,b){return cnt[b]-cnt[a]});
  if(cnt[ks[0]]<2){box.hidden=true;return}
  box.hidden=false;
  var top=ks.slice(0,6), mx=cnt[top[0]];
  box.innerHTML='<h3>많이 마신 브랜드</h3><div style="margin-top:10px">'
    + top.map(function(k){
        var c=catOf(k), nm=c?c.jp:(MINE[k]||{}).jp||'?', ko=(c&&c.ko)||'';
        return '<div style="display:flex;align-items:center;gap:8px;margin:7px 0">'
          +'<span style="flex:0 0 96px;word-break:keep-all">'
          +'<b style="font-family:var(--disp);font-size:15px">'+esc(nm)+'</b>'
          +(ko?'<br><span style="font-size:10.5px;color:var(--ink3)">'+esc(ko)+'</span>':'')+'</span>'
          +'<span style="flex:1;height:9px;background:var(--hair);border-radius:5px;overflow:hidden">'
          +'<span style="display:block;height:100%;width:'+Math.round(cnt[k]/mx*100)+'%;background:var(--me)"></span></span>'
          +'<span style="flex:0 0 30px;text-align:right;font-size:11.5px;color:var(--ink3)">'+cnt[k]+'병</span>'
          +'</div>'}).join('')
    +'</div>';
}
/* 어떤 맛을 모았나. 지역이 「어디」라면 이건 「무엇」이다. */
function renderTasteMix(){
  var box=$('#st-mix'); if(!box)return;
  var cnt=[0,0,0,0,0,0], tot=0;
  Object.keys(MINE).forEach(function(id){
    var c=catOf(id); if(!c||c.t==null)return; cnt[c.t]++; tot++;
  });
  if(!tot){box.hidden=true;return}
  box.hidden=false;
  var mx=Math.max.apply(null,cnt);
  var top=cnt.indexOf(mx);
  box.innerHTML='<h3>어떤 맛을 모았나</h3>'
    +'<p class="diff">가장 많이 담은 쪽은 <b>'+AX[top][1]+'</b>입니다.</p>'
    +'<div style="margin-top:10px">'
    + AX.map(function(a,i){
        return '<div style="display:flex;align-items:center;gap:8px;margin:6px 0">'
          +'<span style="flex:0 0 52px;font-size:11.5px;color:var(--ink2)">'+a[1]+'</span>'
          +'<span style="flex:1;height:9px;background:var(--hair);border-radius:5px;overflow:hidden">'
          +'<span style="display:block;height:100%;width:'+(mx?Math.round(cnt[i]/mx*100):0)
          +'%;background:var(--me)"></span></span>'
          +'<span style="flex:0 0 34px;text-align:right;font-size:11px;color:var(--ink3)">'+cnt[i]+'</span>'
          +'</div>'}).join('')
    +'</div>'
    +'<p class="diff" style="font-size:11px;color:var(--ink3);margin-top:8px">'
    +'맛 6축 중 그 술을 가장 특징짓는 축으로 나눴습니다. 도감에 없는 술은 세지 않았습니다.</p>';
}
/* 아직 안 마신 지역 — 모으는 재미 */
function renderUnvisited(){
  var box=$('#st-todo'); if(!box)return;
  var mine=areaCount(), all={};
  CAT.forEach(function(c){if(c.area)all[c.area]=(all[c.area]||0)+1});
  var left=Object.keys(all).filter(function(a){return !mine[a]});
  if(!left.length){box.hidden=true;return}
  box.hidden=false;
  left.sort(function(a,b){return all[b]-all[a]});
  box.innerHTML='<h3>아직 안 마신 지역 '+left.length+'곳</h3>'
    +'<p class="diff">도감에 술이 많은 순입니다. 눌러서 찾아보세요.</p>'
    +'<div class="chips" style="margin-top:10px">'
    + left.slice(0,10).map(function(a){
        return '<div class="chip" data-area="'+esc(a)+'">'+esc(a)
          +' <span style="opacity:.6;font-size:10px">'+all[a]+'</span></div>'}).join('')
    +'</div>';
}
/* 취향에 가까운 술 — 내가 그린 6축 평균과 거리가 가까운 것 중 아직 안 담은 것.
   도감 맛 데이터와 내 기록만으로 고른다(추천 점수를 지어내지 않는다). */
function renderLike(){
  var box=$('#st-like'); if(!box)return;
  var sum=[0,0,0,0,0,0], n=0;
  Object.keys(NOTE).forEach(function(id){
    logsOf(id).forEach(function(l){
      if(!l.mine)return; l.mine.forEach(function(v,i){sum[i]+=v}); n++});
  });
  if(n<3){
    box.innerHTML='<h3>취향에 가까운 술</h3>'
      +'<p>기록이 <b>'+n+'건</b>입니다. 3건부터 도감에서 비슷한 맛을 찾아 줍니다.</p>';
    return;
  }
  var avg=sum.map(function(v){return v/n});
  var out=CAT.filter(function(c){return c.f&&!ownedBrand(c.id)})
    .map(function(c){
      var d=0; c.f.forEach(function(v,i){d+=(v-avg[i])*(v-avg[i])});
      return {c:c,d:Math.sqrt(d)}})
    .sort(function(a,b){return a.d-b.d}).slice(0,6);
  box.innerHTML='<h3>취향에 가까운 술 <span style="font-weight:400;color:var(--ink3)">기록 '+n+'건 기준</span></h3>'
    +'<p class="diff">내가 그린 맛 평균과 가까운, 아직 안 담은 술입니다.</p>'
    +'<div class="grid" style="margin-top:12px">'
    + out.map(function(o){return cardHTML(o.c,{locked:true})}).join('')
    +'</div>';
}
function renderArea(){
  var box=$('#me-area'); if(!box)return;
  var cnt=areaCount(), names=Object.keys(cnt);
  if(!names.length){
    box.innerHTML='<h3>지역 지도</h3><p>카드를 담으면 <b>어느 지역 술을 마셨는지</b>가 여기에 쌓입니다.'
      +'<br>일본 47개 도도부현 중 몇 곳을 마셨는지 셉니다.</p>';
    return;
  }
  names.sort(function(a,b){return cnt[b]-cnt[a]||a.localeCompare(b,'ko')});
  var max=cnt[names[0]], shown=names.slice(0,10), rest=names.length-shown.length;
  var unknown=Object.keys(MINE).length-names.reduce(function(a,k){return a+cnt[k]},0);
  box.innerHTML='<h3>지역 지도 <span style="font-weight:400;color:var(--ink3)">'
      +names.length+' / 47곳</span></h3>'
    +mapSVG()
    +'<div style="margin-top:14px">'
    + shown.map(function(n){
        return '<div style="display:flex;align-items:center;gap:8px;margin:5px 0">'
          +'<span style="flex:0 0 64px;font-size:11.5px;color:var(--ink2);word-break:keep-all">'+esc(n)+'</span>'
          +'<span style="flex:1;height:9px;background:var(--hair);border-radius:5px;overflow:hidden">'
          +'<span style="display:block;height:100%;width:'+Math.round(cnt[n]/max*100)+'%;background:var(--me)"></span></span>'
          +'<span style="flex:0 0 26px;text-align:right;font-size:11.5px;color:var(--ink3)">'+cnt[n]+'</span>'
          +'</div>'}).join('')
    +'</div>'
    +(rest>0?'<p class="diff" style="margin-top:8px">그 밖에 '+rest+'곳을 더 마셨습니다.</p>':'')
    +(unknown>0?'<p class="diff" style="font-size:11.5px;color:var(--ink3)">도감에 없는 '+unknown
      +'장은 지역을 몰라 세지 않았습니다.</p>':'');
}
/* ── 상세 시트 ── */
function radarSVG(mine,ref,id){
  var CX=150,CY=140,R=96,s=[];
  function pt(i,v){var a=-Math.PI/2+i*Math.PI/3;return [CX+Math.cos(a)*R*v,CY+Math.sin(a)*R*v]}
  function poly(v){return v.map(function(x,i){return pt(i,Math.max(.04,x)).join(',')}).join(' ')}
  s.push('<g stroke="var(--hair)" fill="none">');
  [.25,.5,.75,1].forEach(function(r){s.push('<polygon points="'+poly([r,r,r,r,r,r])+'" opacity=".5"/>')});
  for(var i=0;i<6;i++){var p=pt(i,1);s.push('<line x1="'+CX+'" y1="'+CY+'" x2="'+p[0]+'" y2="'+p[1]+'" opacity=".4"/>')}
  s.push('</g>');
  if(ref)s.push('<polygon points="'+poly(ref)+'" fill="var(--ink3)" fill-opacity=".13" stroke="var(--ink3)" stroke-width="1.3" stroke-dasharray="3 3"/>');
  s.push('<polygon points="'+poly(mine)+'" fill="var(--me)" fill-opacity=".2" stroke="var(--me)" stroke-width="2.2"/>');
  AX.forEach(function(a,i){var p=pt(i,1.26);
    s.push('<text x="'+p[0]+'" y="'+p[1]+'" text-anchor="middle" font-size="12" fill="var(--ink2)" font-family="Yu Mincho,serif">'+a[0]+'</text>');
    s.push('<text x="'+p[0]+'" y="'+(p[1]+11)+'" text-anchor="middle" font-size="9" fill="var(--ink3)">'+a[1]+'</text>');
    var q=pt(i,mine[i]);
    s.push('<circle cx="'+q[0]+'" cy="'+q[1]+'" r="9" fill="var(--me)" data-ax="'+i+'" style="cursor:grab"/>')});
  return '<svg class="radar"'+(id?' id="'+id+'"':'')+' viewBox="0 0 300 290" style="touch-action:none">'
    +s.join('')+'</svg>';
}
function openSheet(id){
  curId=id;
  if(!catOf(id)&&!MINE[id])return;
  var s=cardOf(id);
  var has=!!MINE[id], logs=logsOf(id), n=lastLog(id);
  /* 도감에서 브랜드를 열었는데 그 브랜드로 담은 병이 있으면 먼저 보여준다 —
     같은 브랜드의 다른 병을 또 담아 중복이 생기는 걸 막는다. */
  var vars_= has?[]:variantsOf(id);
  var _c=catOf(id), c_ko=(_c&&_c.ko)||'';
  if(c_ko&&(s.ko||'').indexOf(c_ko)===0)c_ko='';   /* 제품명이 이미 독음으로 시작하면 중복 */
  var mine=n?n.mine.slice():(s.f?s.f.slice():[.5,.5,.5,.5,.5,.5]);
  var st={tags:n?n.tags.slice():[],temp:n?n.temp:null,memo:n?n.memo:'',again:n?n.again:null,
          at:(n&&n.at?n.at.slice(0,10):((MINE[id]||{}).at||new Date().toISOString().slice(0,10)))};
  function chips(){return TAGS.map(function(t){
    return '<div class="chip'+(st.tags.indexOf(t[0])>=0?' on':'')+'" data-tag="'+t[0]+'">'
      +'<b style="font-family:var(--disp)">'+t[0]+'</b> <span style="opacity:.7;font-size:10px">'+t[1]+'</span></div>'}).join('')}
  function temps(){return TEMPS.map(function(t,i){
    return '<div class="temp'+(st.temp===i?' on':'')+'" data-temp="'+i+'"><b>'+t[0]+'</b><span>'+t[1]+'</span></div>'}).join('')}
  $('#sheetbox').innerHTML='<div class="bar"></div>'
    +'<h2>'+esc(s.jp)+(c_ko?' <span style="font-size:14px;color:var(--ink3);font-family:var(--body);letter-spacing:0">'+esc(c_ko)+'</span>':'')+'</h2><p class="meta">'
    +esc([s.ko,brewOf(s),s.area&&s.areaJp&&s.area!==s.areaJp?s.area+' '+s.areaJp:(s.area||s.areaJp||'')]
          .filter(Boolean).join(' · '))+'</p>'
    + (has ? '' : '<div class="acts">'
           + '<button class="pri" id="a-add">마셨어요 — 카드로 담기</button>'
           + '<button class="ghost" id="a-close">닫기</button></div>')
    + (has ? '<div id="noteui">'
        + (picOf(id)?'<div class="picbox"><img src="'+picOf(id)+'" alt="">'
            +(PIC[id]?'<button class="picx" id="a-picdel">사진 지우기</button>':'')+'</div>':'')
        /* 한 번 누르면 기록이 남는다. 빈 칸 여럿과 6축 드래그를 한꺼번에 들이밀면
           「뭘 써야 하지」에서 멈춘다 — Untappd 가 빠른 이유는 체크인이 한 동작이라서다. */
        +'<div class="quick"><p class="qt">어땠어요?</p><div class="qb" id="c-again">'
        + ['좋았다','괜찮다','아쉬웠다'].map(function(t,k){
            return '<button class="q'+(st.again===k?' on':'')+'" data-ag="'+k+'">'+t+'</button>'}).join('')
        +'</div><p class="qs">한 번 누르면 오늘 날짜로 기록됩니다.</p></div>'
        /* 나머지는 접어 둔다 — 쓰고 싶은 사람만 편다 */
        +'<button class="more" id="c-more" aria-expanded="false">맛까지 남기기<span>＋</span></button>'
        +'<div id="deep" hidden>'
        +'<div class="sec"><h3>어떤 맛이었나요<span class="opt">골라도 되고 안 골라도 됩니다</span></h3>'
        +'<div class="chips" id="c-tags">'+chips()+'</div></div>'
        +'<div class="sec"><h3>어떻게 마셨나요<span class="opt">온도</span></h3>'
        +'<div class="temps" id="c-temps">'+temps()+'</div></div>'
        +'<div class="sec"><h3>맛을 그려볼까요<span class="opt">끌어서 옮기면 됩니다</span></h3>'
        +radarSVG(mine,s.f,'rad')
        +'<p class="legend">'+(s.f?'<span style="color:var(--ink3)">— — 데이터 평균</span> &nbsp; ':'')
        +'<span style="color:var(--me)">—— 내가 느낀 값</span></p>'
        +'<p class="diff" id="diff"></p>'
        + (s.f?'<p class="qs">그냥 두면 데이터 평균이 들어갑니다. 달랐던 축만 옮기세요.</p>':'')
        +'</div>'
        +'<div class="sec"><h3>한 줄<span class="opt">안 써도 됩니다</span></h3>'
        +'<div class="chips" id="c-quick">'
        + ['혼자 마신 밤','좋은 사람들과','안주 없이도 좋았다','처음 마셔봤다','또 사고 싶다']
            .map(function(t){return '<div class="chip" data-memo="'+esc(t)+'">'+t+'</div>'}).join('')
        +'</div>'
        +'<textarea id="c-memo" placeholder="눌러서 넣거나 직접 쓰세요">'+esc(st.memo)+'</textarea></div>'
        +'<div class="sec"><h3>마신 날</h3><input type="date" id="c-at" value="'+esc(st.at)+'"'
        +' max="'+new Date().toISOString().slice(0,10)+'"></div>'
        +'</div>'
        + (logs.length ? '<div class="sec"><h3>지난 기록 '+logs.length+'회</h3><div class="hist">'
            + logs.slice().reverse().map(function(l,i){
                var idx=logs.length-1-i;
                return '<div class="hrow" data-log="'+idx+'"><b>'+esc((l.at||'').slice(0,10))+'</b>'
                  +'<span>'+esc(l.memo||(l.tags||[]).map(tagKo).join(' · ')||AGAIN[l.again]||'기록')+'</span></div>'}).join('')
            + '</div><p class="qs">탭하면 그때 쓴 값을 불러옵니다. 저장하면 새 기록으로 쌓입니다.</p></div>' : '')
        + (blankLeft(id)
            ? '<div class="acts" style="margin-top:18px">'
              +'<button class="pri" id="a-next">저장하고 다음 카드 ('+blankLeft(id)+'장 남음)</button></div>'
            : '')
        +'<div class="acts sub" style="margin-top:22px">'
        +'<button id="a-img">이미지로 저장</button>'
        +'<button id="a-pic">'+(picOf(id)?'사진 바꾸기':'내 사진 넣기')+'</button>'
        + (catOf(id)?'<button id="a-more">같은 술 다른 병 담기</button>':'')
        +'<button class="ghost" id="a-close">닫기</button></div>'
        +'<div class="acts" style="margin-top:10px"><button class="del" id="a-del">컬렉션에서 빼기</button></div>'
        +'</div>'
      : (vars_.length
          ? '<div class="sec"><h3>이 술로 담은 병 '+vars_.length+'개</h3><div class="hist">'
            + vars_.map(function(k){var c=cardOf(k);
                return '<div class="hrow" data-open="'+esc(k)+'"><b>'+esc((c.at||'').slice(0,10))+'</b>'
                  +'<span>'+esc(c.ko||c.jp)+'</span></div>'}).join('')
            + '</div><p class="diff" style="margin-top:8px;font-size:11.5px">탭하면 그 병의 카드를 엽니다.</p></div>'
          : '')
        + '<p class="diff" style="margin-top:14px">'
        + (vars_.length?'다른 병을 마셨다면 위 버튼으로 담으세요.':'아직 담지 않은 술입니다.')
        + '</p>');
  $('#sheet').classList.add('on');
  $('#sheetbox').scrollTop=0;

  function saveNote(id,close){
    var ta=$('#c-memo'); if(ta)st.memo=ta.value||'';
    var day=($('#c-at')||{}).value||'';
    var at=day?day+'T00:00:00.000Z':new Date().toISOString();
    var arr=logsOf(id).slice();
    var last=arr.length?arr[arr.length-1]:null;
    var rec={at:at,mine:mine,tags:st.tags,temp:st.temp,memo:st.memo,again:st.again};
    /* 「어땠어요?」를 누른 뒤 태그를 더 고르면 같은 기록에 얹는다 — 두 건이 되면 안 된다 */
    if(last&&(last.at||'').slice(0,10)===at.slice(0,10)&&last._s){rec._s=1;arr[arr.length-1]=rec}
    else {rec._s=1;arr.push(rec)}
    NOTE[id]=arr; save(K_NOTE,NOTE); refresh();
    toast(close&&arr.length>1?'새 기록으로 쌓았습니다 ('+arr.length+'회)':'기록했습니다');
  }
  function diff(){
    var el=$('#diff'); if(!el)return;
    if(!s.f){el.innerHTML='<b>도감에 맛 데이터가 없는 술</b>입니다 — 지금 그린 값이 첫 기록이 됩니다.';return}
    var d=[];mine.forEach(function(v,i){var g=v-s.f[i];
      if(Math.abs(g)>.18)d.push(AX[i][1]+(g>0?' 더 강하게':' 더 약하게'))});
    el.innerHTML=d.length?'데이터보다 <b>'+d.join('</b>, <b>')+'</b> 느꼈습니다.':'데이터 평균과 비슷하게 느꼈습니다.';
  }
  function redrawRadar(){
    var wrap=$('#noteui'); if(!wrap)return;
    var old=wrap.querySelector('#rad'); if(old)old.outerHTML=radarSVG(mine,s.f,'rad');
    bindRadar(); diff();
  }
  function bindRadar(){
    var rad=$('#noteui #rad'); if(!rad)return; var drag=null;
    function xy(e){var r=rad.getBoundingClientRect(),t=e.touches?e.touches[0]:e;
      return [(t.clientX-r.left)*300/r.width,(t.clientY-r.top)*290/r.height]}
    rad.addEventListener('pointerdown',function(e){
      if(e.target.tagName!=='circle')return; drag=+e.target.dataset.ax;
      rad.setPointerCapture(e.pointerId); e.preventDefault()});
    rad.addEventListener('pointermove',function(e){
      if(drag===null)return; var p=xy(e),a=-Math.PI/2+drag*Math.PI/3;
      var v=((p[0]-150)*Math.cos(a)+(p[1]-140)*Math.sin(a))/96;
      mine[drag]=Math.max(0,Math.min(1,v)); redrawRadar(); e.preventDefault()});
    rad.addEventListener('pointerup',function(){drag=null});
    rad.addEventListener('pointercancel',function(){drag=null});
  }
  bindRadar(); diff();

  /* 같은 브랜드라도 병마다 다른 술이다(칸키쿠만 14병). 담을 때 한 번 물어
     카드가 병 단위로 남게 한다 — 비우면 브랜드 카드 한 장으로 담긴다. */
  function askProd(){
    var old=$('#prodask'); if(old){old.scrollIntoView({block:'center'});$('#p-name').focus();return}
    var el=document.createElement('div');
    el.id='prodask'; el.className='sec';
    el.innerHTML='<h3>어떤 병이었나요 <span style="color:var(--ink3);font-weight:400">(선택)</span></h3>'
      +'<textarea id="p-name" style="min-height:42px" placeholder="예: 준마이다이긴죠 나마 720ml"></textarea>'
      +'<div class="acts" style="margin-top:10px">'
      +'<button class="pri" id="p-ok">이 이름으로 담기</button>'
      +'<button class="ghost" id="p-skip">이름 없이 담기</button></div>';
    $('#sheetbox').appendChild(el);
    el.scrollIntoView({block:'center'}); $('#p-name').focus();
  }

  var box=$('#sheetbox');
  box.onclick=function(e){
    var t=e.target.closest('[data-tag],[data-temp],[data-ag],[data-log],[data-open],[data-memo],'
      +'#a-add,#a-more,#a-del,#a-note,#a-next,#a-img,#a-close,#p-ok,#p-skip,#a-pic,#a-picdel,#c-more');
    if(!t)return;
    if(t.id==='a-pic'){
      var fp=$('#picfile'); fp.dataset.for=id; fp.value=''; fp.click(); return}
    if(t.id==='a-picdel'){
      if(!confirm('이 카드의 사진을 지웁니다.'))return;
      picDel(id).then(function(){refresh();openSheet(id)}); return}
    if(t.dataset.open!==undefined){openSheet(t.dataset.open);return}
    if(t.dataset.tag!==undefined){var i=st.tags.indexOf(t.dataset.tag);
      i<0?st.tags.push(t.dataset.tag):st.tags.splice(i,1);$('#c-tags').innerHTML=chips();
      if(st.again!==null)saveNote(id,false);return}
    if(t.dataset.temp!==undefined){st.temp=+t.dataset.temp;$('#c-temps').innerHTML=temps();
      if(st.again!==null)saveNote(id,false);return}
    if(t.dataset.ag!==undefined){
      st.again=+t.dataset.ag;
      $$('#c-again .q').forEach(function(b){b.classList.toggle('on',+b.dataset.ag===st.again)});
      saveNote(id,false);      /* 한 번 누르면 바로 남는다 */
      return}
    if(t.dataset.memo!==undefined){
      var ta=$('#c-memo'); if(!ta)return;
      ta.value = ta.value ? (ta.value.indexOf(t.dataset.memo)>=0 ? ta.value
                   : ta.value.replace(/\s*$/,'')+' '+t.dataset.memo) : t.dataset.memo;
      st.memo=ta.value; if(st.again!==null)saveNote(id,false); return}
    if(t.id==='c-more'){
      var d=$('#deep'), open=d.hidden;
      d.hidden=!open; t.setAttribute('aria-expanded',open?'true':'false');
      t.innerHTML=(open?'접기':'맛까지 남기기')+'<span>'+(open?'－':'＋')+'</span>';
      if(open){bindRadar();diff();d.scrollIntoView({block:'nearest',behavior:'smooth'})}
      return}
    if(t.dataset.log!==undefined){
      var l=logsOf(id)[+t.dataset.log]; if(!l)return;
      mine=l.mine.slice(); st={tags:(l.tags||[]).slice(),temp:l.temp,memo:l.memo||'',again:l.again,
                               at:(l.at||'').slice(0,10)||st.at};
      var ta=$('#c-memo'); if(ta)ta.value=st.memo;
      var da=$('#c-at'); if(da)da.value=st.at;
      $('#c-tags').innerHTML=chips(); $('#c-temps').innerHTML=temps(); $('#c-again').innerHTML=agains();
      redrawRadar(); toast((l.at||'').slice(0,10)+' 기록을 불러왔습니다'); return}
    if(t.id==='a-img'){exportCard(id);return}
    if(t.id==='a-close'){closeSheet();return}
    if(t.id==='a-add'||t.id==='a-more'){askProd();return}
    if(t.id==='p-ok'||t.id==='p-skip'){
      var pn=t.id==='p-ok'?(($('#p-name')||{}).value||'').trim():'';
      var key=pn?baseOf(id)+'#'+pn:baseOf(id);
      if(MINE[key]){toast('이미 담은 병입니다');openSheet(key);return}
      MINE[key]={at:new Date().toISOString().slice(0,10),jp:s.jp,name:pn};
      save(K_MINE,MINE); refresh(); getCard(key); openSheet(key); return}
    if(t.id==='a-del'){
      if(!confirm('이 카드를 컬렉션에서 뺍니다. 기록도 함께 지워집니다.'))return;
      delete MINE[id]; delete NOTE[id]; save(K_MINE,MINE); save(K_NOTE,NOTE);
      if(PIC[id])picDel(id);
      toast('뺐습니다'); closeSheet(); refresh(); return}
    if(t.id==='a-note'||t.id==='a-next'){
      saveNote(id,true);
      if(t.id==='a-next'){
        var nx=nextBlank(id);
        if(nx){toast('저장했습니다 — 다음 카드');openSheet(nx);return}
        toast('저장했습니다 — 안 쓴 카드가 없습니다');closeSheet();return}
      closeSheet(); return}
  };
}
/* 바텀시트를 손가락으로 내려 닫는다. 버튼을 찾아 눌러야 하면 모달처럼 느껴진다
   — 모바일 바텀시트의 기본 동작이다(2026-09-16 「갑자기 이상한 모달이 뜬다」 지적).
   시트 안에 레이더 드래그가 있어, 손잡이와 제목 영역에서 시작한 드래그만 받는다. */
(function(){
  var box=null, startY=0, cur=0, dragging=false;
  function grabbable(t){
    if(!t)return false;
    if(t.closest('#rad,textarea,input,button,.chip,.temp,.ag,.hrow,.acts'))return false;
    return !!t.closest('.bar,h2,.meta,.box');
  }
  document.addEventListener('pointerdown',function(e){
    var b=e.target.closest&&e.target.closest('#sheetbox'); if(!b)return;
    if(b.scrollTop>4)return;                 /* 안쪽이 스크롤 중이면 시트를 끌지 않는다 */
    if(!grabbable(e.target))return;
    box=b; startY=e.clientY; cur=0; dragging=true;
    box.style.transition='none';
  });
  document.addEventListener('pointermove',function(e){
    if(!dragging||!box)return;
    var dy=e.clientY-startY;
    if(dy<0){cur=0;box.style.transform='';return}
    cur=dy; box.style.transform='translateY('+dy+'px)';
  });
  function end(){
    if(!dragging||!box)return;
    dragging=false;
    box.style.transition='transform .22s ease';
    if(cur>110){ box.style.transform='translateY(100%)';
      setTimeout(function(){closeSheet();box.style.transition='';box.style.transform='';},200); }
    else box.style.transform='';
    box=null;
  }
  document.addEventListener('pointerup',end);
  document.addEventListener('pointercancel',end);
})();
/* 담은 순간 — 잔에 술을 따르고 카드가 돌아 나온다.
   토스트 한 줄로 끝내면 모은 느낌이 안 남는다. 따르는 1초가 그 자리를 만든다. */
function pourSVG(f){
  var h=hue(f||[.5,.5,.5,.5,.5,.5]);
  return '<svg class="pour" viewBox="0 0 200 150" aria-hidden="true">'
    /* 병 — 기울어져 들어온다 */
    +'<g class="pb">'
    +'<path d="M52 8 L74 8 L74 38 C74 45 86 49 86 66 L86 104 Q86 110 79 110 L47 110 Q40 110 40 104 L40 66 C40 49 52 45 52 38 Z"'
    +' fill="hsl('+h+',34%,60%)" fill-opacity=".7" stroke="hsl('+h+',30%,44%)" stroke-width="2"/>'
    +'<rect x="50" y="2" width="26" height="9" rx="2.5" fill="#8a7645"/>'
    +'<rect x="46" y="70" width="34" height="26" rx="2" fill="#fbf8f0" opacity=".95"/>'
    +'<rect x="46" y="70" width="34" height="26" rx="2" fill="none" stroke="#8a7645" stroke-opacity=".5"/>'
    +'</g>'
    /* 줄기 */
    +'<rect class="pj" x="118" y="34" width="4" height="52" rx="2" fill="hsl('+h+',44%,62%)"/>'
    /* 오초코 */
    +'<g>'
    +'<clipPath id="cupclip"><path d="M104 96 L146 96 L140 132 Q139 138 132 138 L118 138 Q111 138 110 132 Z"/></clipPath>'
    +'<rect class="pl" x="104" y="138" width="42" height="44" fill="hsl('+h+',44%,62%)" clip-path="url(#cupclip)"/>'
    +'<path d="M104 96 L146 96 L140 132 Q139 138 132 138 L118 138 Q111 138 110 132 Z"'
    +' fill="none" stroke="#e7e4dc" stroke-width="2.6" stroke-opacity=".9"/>'
    +'<ellipse cx="125" cy="96" rx="21" ry="4.5" fill="none" stroke="#e7e4dc" stroke-width="2.6" stroke-opacity=".9"/>'
    +'</g></svg>';
}
function getCard(id){
  var c=catOf(id)?cardOf(id):null; if(!c)return;
  var w=document.createElement('div');
  w.className='got';
  w.innerHTML='<div class="got-in">'
    +'<div class="got-pour">'+pourSVG(c.f)+'</div>'
    +'<div class="got-card"><p class="got-t">카드를 담았습니다</p>'
    +'<div class="got-c">'+cardHTML(c)+'</div>'
    +(c.no?'<p class="got-n">No.'+c.no+(c.rank?' · 인기 '+c.rank+'위':'')+'</p>':'')
    +'</div></div>';
  document.body.appendChild(w);
  requestAnimationFrame(function(){w.classList.add('on')});
  setTimeout(function(){w.classList.add('done')},1150);      /* 따르기 끝 → 카드 */
  setTimeout(function(){w.classList.remove('on');
    setTimeout(function(){w.remove()},320)},3100);
  w.addEventListener('click',function(){w.classList.remove('on');
    setTimeout(function(){w.remove()},320)});
}
function openManual(){
  $('#sheetbox').innerHTML='<div class="bar"></div>'
    +'<h2>직접 추가</h2><p class="meta">도감에 없는 술을 카드로 만듭니다.</p>'
    +'<div class="sec"><h3>사케명 <span style="color:#a8534a">*</span></h3>'
    +'<textarea id="m-jp" style="min-height:42px" placeholder="예: 埋火 · 우즈미비"></textarea></div>'
    +'<div class="sec"><h3>양조장 · 지역 (선택)</h3>'
    +'<textarea id="m-ko" style="min-height:42px" placeholder="예: 山口県"></textarea></div>'
    +'<div class="acts"><button class="pri" id="m-save">카드로 담기</button>'
    +'<button class="ghost" id="m-cancel">취소</button></div>';
  $('#sheet').classList.add('on');
  $('#sheetbox').scrollTop=0;
  $('#sheetbox').onclick=function(e){
    var t=e.target.closest('#m-save,#m-cancel'); if(!t)return;
    if(t.id==='m-cancel'){closeSheet();return}
    var jp=($('#m-jp').value||'').trim();
    if(!jp){toast('사케명을 입력해 주세요');return}
    var id='own:'+Date.now().toString(36);
    MINE[id]={at:new Date().toISOString().slice(0,10),jp:jp,name:($('#m-ko').value||'').trim()};
    save(K_MINE,MINE); toast('담았습니다'); closeSheet(); refresh(); go('mine');
  };
}
function tagKo(jp){for(var i=0;i<TAGS.length;i++)if(TAGS[i][0]===jp)return TAGS[i][1];return jp}
/* 캔버스 줄바꿈 — 폭을 넘으면 접고, 최대 줄 수를 넘으면 말줄임 */
function wrapText(x,text,cx,y,maxW,lh,maxLines){
  var words=String(text||'').split(/\s+/).filter(Boolean), lines=[], cur='';
  words.forEach(function(w){
    var t=cur?cur+' '+w:w;
    if(x.measureText(t).width<=maxW){cur=t;return}
    if(cur)lines.push(cur);
    cur=w;
  });
  if(cur)lines.push(cur);
  if(lines.length>maxLines){lines=lines.slice(0,maxLines);
    lines[maxLines-1]=lines[maxLines-1].replace(/.$/,'')+'…'}
  lines.forEach(function(l,i){x.fillText(l,cx,y+i*lh)});
  return lines.length;
}
/* 카드를 이미지로 — 인스타 피드 비율(4:5). 화면 카드는 CSS 로 그려서 캡처가 안 되므로
   Canvas 에 다시 그린다. 외부 라이브러리 없이 끝난다. */
function exportCard(id){
  if(!catOf(id)&&!MINE[id])return;
  var s=cardOf(id);
  var log=lastLog(id), prem=isPrem(s), mypic=picOf(id);
  var W=1080,H=1350,c=document.createElement('canvas');c.width=W;c.height=H;
  var x=c.getContext('2d');
  var dark=false, bg='#f4f1e9', ink='#211d18', ink2='#6b655b', hair='#cfc7b6';
  x.fillStyle=bg;x.fillRect(0,0,W,H);
  if(prem){ x.strokeStyle='#b5872c';x.lineWidth=6;x.strokeRect(3,3,W-6,H-6); }
  /* 상단 맛색 밴드 */
  x.fillStyle='hsl('+hue(s.f||[.5,.5,.5,.5,.5,.5])+',42%,56%)';x.fillRect(0,0,W,14);
  /* 레이더 — 사진이 있으면 그리지 않는다(사진 위에 겹치면 둘 다 안 읽힌다) */
  var CX=W/2,CY=430,R=195;
  if(mypic){
    if(s.t!=null){
      x.textAlign='center'; x.fillStyle=ink2; x.font='28px system-ui,sans-serif';
      x.fillText(AX[s.t][0]+' · '+AX[s.t][1], W/2, 770);
    }
  }else{
  function pt(i,v){var a=-Math.PI/2+i*Math.PI/3;return [CX+Math.cos(a)*R*v,CY+Math.sin(a)*R*v]}
  function path(vals){x.beginPath();vals.forEach(function(v,i){var p=pt(i,Math.max(.05,v));
    i?x.lineTo(p[0],p[1]):x.moveTo(p[0],p[1])});x.closePath()}
  x.strokeStyle=hair;x.lineWidth=1.5;
  [.25,.5,.75,1].forEach(function(r){path([r,r,r,r,r,r]);x.stroke()});
  for(var i=0;i<6;i++){var p=pt(i,1);x.beginPath();x.moveTo(CX,CY);x.lineTo(p[0],p[1]);x.stroke()}
  if(s.f){x.setLineDash([7,7]);x.strokeStyle=ink2;x.lineWidth=2.5;path(s.f);x.stroke();x.setLineDash([])}
  var mine=log?log.mine:(s.f||[.5,.5,.5,.5,.5,.5]);
  x.fillStyle=dark?'rgba(201,168,106,.22)':'rgba(31,111,74,.2)';
  x.strokeStyle=dark?'#c9a86a':'#1f6f4a';x.lineWidth=5;path(mine);x.fill();x.stroke();
  /* 축 라벨 */
  x.fillStyle=ink2;x.textAlign='center';
  var AXJ=['華やか','芳醇','重厚','穏やか','ドライ','軽快'];
  AXJ.forEach(function(t,i){var p=pt(i,1.2);
    x.font='30px "Yu Mincho","Hiragino Mincho ProN",serif';x.fillText(t,p[0],p[1]+10);
    x.font='20px system-ui';x.fillStyle=dark?'#8c8375':'#9a9284';
    x.fillText(AX[i][1],p[0],p[1]+38);x.fillStyle=ink2});
  }
  /* 이름 — 일본어 이름 옆에 한국어 독음을 붙인다. 이미지는 앱 밖으로 나가는 결과물이라
     한자만 남으면 읽을 수가 없다. 제품명이 이미 독음으로 시작하면 겹치므로 생략한다. */
  var cat=catOf(id), yomi=(cat&&cat.ko)||'';
  if(yomi&&(s.ko||'').indexOf(yomi)===0)yomi='';
  x.textAlign='center';x.fillStyle=ink;
  x.font='96px "Yu Mincho","Hiragino Mincho ProN",serif';
  if(yomi){
    var wJp=x.measureText(s.jp).width;
    x.font='30px system-ui,sans-serif';
    var wKo=x.measureText(yomi).width, gap=18, left=(W-(wJp+gap+wKo))/2;
    x.textAlign='left';
    x.font='96px "Yu Mincho","Hiragino Mincho ProN",serif';
    x.fillText(s.jp,left,870);
    x.font='30px system-ui,sans-serif';x.fillStyle=ink2;
    x.fillText(yomi,left+wJp+gap,870);
    x.textAlign='center';
  }else{
    x.fillText(s.jp,W/2,870);
  }
  /* 제품명은 길다("아라마사 No.6 X-type 나마 720ml"). 한 줄로 자르면 정보가 날아가므로
     폭에 맞춰 두 줄까지 접는다. */
  x.font='30px system-ui,sans-serif';x.fillStyle=ink2;
  wrapText(x,(s.ko||brewOf(s)),W/2,920,W-200,38,2);
  /* 한 줄 */
  if(log&&log.memo){
    x.font='italic 34px system-ui,sans-serif';x.fillStyle=ink;
    var m=log.memo.length>30?log.memo.slice(0,30)+'…':log.memo;
    x.fillText('\u201c'+m+'\u201d',W/2,1000);
  }
  /* 태그·온도 */
  if(log){
    /* 이미지는 밖으로 나가는 결과물이라 한국어로 적는다(앱 화면은 일본어 병기) */
    var line=[];
    if(typeof log.temp==='number')line.push(TEMPS[log.temp][1]);
    (log.tags||[]).slice(0,4).forEach(function(t){line.push(tagKo(t))});
    if(line.length){x.font='28px system-ui,sans-serif';x.fillStyle=ink2;
      x.fillText(line.join('  \u00b7  '),W/2,1068)}
  }
  /* 하단 */
  x.strokeStyle=hair;x.lineWidth=1.5;x.beginPath();x.moveTo(90,1170);x.lineTo(W-90,1170);x.stroke();
  x.font='24px ui-monospace,Menlo,monospace';x.textAlign='left';x.fillStyle=ink2;
  x.fillText((s.area||'').toString(),90,1218);
  x.textAlign='right';x.fillText('SAKE CARD',W-90,1218);
  x.textAlign='center';x.font='20px system-ui';x.fillStyle=dark?'#7d7466':'#9a9284';
  x.fillText('\u3055\u3051\u306e\u308f\u30c7\u30fc\u30bf\u3092\u52a0\u5de5\u3057\u3066\u5229\u7528', W/2, 1290);

  function finish(){
    c.toBlob(function(b){
    var a=document.createElement('a');a.href=URL.createObjectURL(b);
      a.download='sake_'+((s.jp||'card')+(s.ko?'_'+s.ko:''))
        .replace(/[\\/:*?"<>|]/g,'').slice(0,60)+'.png';a.click();
      toast('이미지를 저장했습니다');
    },'image/png');
  }
  if(!mypic)return finish();
  /* 내 사진이 있으면 위쪽에 얹고 아래를 어둡게 덮어 글씨가 읽히게 한다 */
  var im=new Image();
  im.onload=function(){
    var ph=Math.round(H*0.52);
    var r=Math.max(W/im.width, ph/im.height);
    var dw=im.width*r, dh=im.height*r;
    x.save(); x.beginPath(); x.rect(0,0,W,ph); x.clip();
    x.drawImage(im,(W-dw)/2,(ph-dh)/2,dw,dh);
    var g=x.createLinearGradient(0,ph*0.45,0,ph);
    g.addColorStop(0,'rgba(0,0,0,0)'); g.addColorStop(1,bg);
    x.fillStyle=g; x.fillRect(0,0,W,ph);
    x.restore();
    finish();
  };
  im.onerror=finish;
  im.src=mypic;
}
function closeSheet(){$('#sheet').classList.remove('on');curId=null}

/* ── 탭 ── */
function go(name){
  $$('.pane').forEach(function(p){p.classList.toggle('on',p.id==='p-'+name)});
  $$('.nav button').forEach(function(b){b.classList.toggle('on',b.dataset.go===name)});
  var T={home:['사케 카드','마신 술을 한 장씩 모읍니다'],
         dex:['도감','마신 술을 찾아 담아 보세요'],
         mine:['내 카드','눌러서 뒤집어 보세요'],
         stat:['분석','모은 카드가 말해 주는 것'],
         me:['기록','백업과 저장 위치']};
  $('#ttl').textContent=T[name][0]; $('#sub').textContent=T[name][1];
  window.scrollTo(0,0);
  if(name==='home')renderHome(); if(name==='dex')renderDex(); if(name==='mine')renderMine();
  if(name==='stat')renderStats();
  if(name==='me')renderMe();
  try{localStorage.setItem('sake.tab',name)}catch(e){}
  saveView();
}
window.go=go;
/* 기록의 흐름 — 언제 무엇을 담고 무엇을 썼나. 카드 격자는 「무엇을 모았나」를 보여주지만
   「어떻게 쌓였나」는 시간축이라야 보인다. */
function renderTimeline(){
  var box=$('#me-line'); if(!box)return;
  var ev=[];
  Object.keys(MINE).forEach(function(id){
    var at=(MINE[id].at||'').slice(0,10); if(at)ev.push({at:at,id:id,kind:'담음'});
  });
  Object.keys(NOTE).forEach(function(id){
    logsOf(id).forEach(function(l){
      var at=(l.at||'').slice(0,10); if(at)ev.push({at:at,id:id,kind:'기록',memo:l.memo});
    });
  });
  if(!ev.length){box.hidden=true;return}
  box.hidden=false;
  ev.sort(function(a,b){return b.at.localeCompare(a.at)});
  var lim=box.dataset.all==='1'?ev.length:14;
  var days={}, order=[];
  ev.slice(0,lim).forEach(function(e){
    if(!days[e.at]){days[e.at]=[];order.push(e.at)}
    days[e.at].push(e);
  });
  box.innerHTML='<h3>기록의 흐름 <span style="font-weight:400;color:var(--ink3)">'
      +ev.length+'건</span></h3>'
    +'<div class="tl">'
    + order.map(function(d){
        return '<div class="tl-d"><b>'+esc(d.replace(/-/g,'.'))+'</b><div>'
          + days[d].map(function(e){
              var cat=catOf(e.id), c=cat?cardOf(e.id):{jp:(MINE[e.id]||{}).jp||'?'};
              var yo=(cat&&cat.ko)||'';
              return '<div class="tl-i" data-open-sheet="'+esc(e.id)+'">'
                +'<span class="tl-k'+(e.kind==='기록'?' n':'')+'">'+e.kind+'</span>'
                +'<span class="tl-n">'+esc(c.jp)+'</span>'
                + (yo?'<span class="tl-y">'+esc(yo)+'</span>':'')
                + (e.memo?'<span class="tl-m">'+esc(e.memo)+'</span>':'')
                +'</div>'}).join('')
          +'</div></div>'}).join('')
    +'</div>'
    + (ev.length>lim?'<div class="acts" style="margin-top:12px">'
        +'<button id="tl-more">더 보기 ('+(ev.length-lim)+'건)</button></div>':'');
}
function renderMe(){
  var m=Object.keys(MINE).length,n=noteCount();
  var b=sinceBackup();
  $('#me-sum').innerHTML='카드 <b>'+m+'종</b> · 기록 <b>'+n+'건</b>'
    +(m?'<br>가장 최근 담은 카드: '+esc(nameOf(mineList()[0])):'')
    +(m? '<br><span style="color:'+(b.never||b.cards+b.notes>=10?'#a8534a':'var(--ink3)')+'">'
        +(b.never?'아직 백업한 적이 없습니다'
                 :(b.cards+b.notes? b.at+' 백업 이후 카드 '+b.cards+'장·노트 '+b.notes+'건이 쌓였습니다'
                                  : b.at+'에 백업했습니다 — 그 뒤로 바뀐 것 없음'))
        +'</span>' : '');
  renderTimeline();
}
/* 내 취향 — 내가 그린 6축의 평균. 도감 평균과 겹쳐 "나는 무엇을 더 세게 느끼나"를 본다.
   노트가 적을 때 단정하지 않도록 건수를 함께 보여준다. */
function renderTaste(total){
  var box=$('#me-taste'); if(!box)return;
  if(!total){box.innerHTML='<h3>내 취향</h3><p>몇 잔 기록하면 여기에 <b>내가 느낀 맛의 평균</b>이 그려집니다.<br>'
    +'도감 평균과 겹쳐 보여 어떤 맛을 강하게 느끼는지 드러납니다.</p>';return}
  var sum=[0,0,0,0,0,0], ref=[0,0,0,0,0,0], cnt=0, refN=0;
  var tagCnt={}, tempCnt={}, againCnt=[0,0,0];
  Object.keys(NOTE).forEach(function(id){
    var s=catOf(id);
    logsOf(id).forEach(function(l){
      if(!l.mine)return;
      l.mine.forEach(function(v,i){sum[i]+=v}); cnt++;
      (l.tags||[]).forEach(function(t){tagCnt[t]=(tagCnt[t]||0)+1});
      if(typeof l.temp==='number')tempCnt[l.temp]=(tempCnt[l.temp]||0)+1;
      if(typeof l.again==='number')againCnt[l.again]++;
    });
    if(s&&s.f){s.f.forEach(function(v,i){ref[i]+=v});refN++}
  });
  if(!cnt){box.innerHTML='<h3>내 취향</h3><p>아직 그린 값이 없습니다.</p>';return}
  var avg=sum.map(function(v){return v/cnt});
  var refAvg=refN?ref.map(function(v){return v/refN}):null;
  var gaps=[];
  if(refAvg)avg.forEach(function(v,i){var g=v-refAvg[i];
    if(Math.abs(g)>.1)gaps.push([AX[i][1],g])});
  gaps.sort(function(a,b){return Math.abs(b[1])-Math.abs(a[1])});
  var topTags=Object.keys(tagCnt).sort(function(a,b){return tagCnt[b]-tagCnt[a]}).slice(0,5);
  var topTemp=Object.keys(tempCnt).sort(function(a,b){return tempCnt[b]-tempCnt[a]})[0];
  var again=againCnt[0], agTot=againCnt[0]+againCnt[1]+againCnt[2];
  box.innerHTML='<h3>내 취향 <span style="font-weight:400;color:var(--ink3)">기록 '+cnt+'건 기준</span></h3>'
    +radarSVG(avg, refAvg)
    +'<p class="legend">'+(refAvg?'<span style="color:var(--ink3)">— — 도감 평균</span> &nbsp; ':'')
    +'<span style="color:var(--me)">—— 내가 그린 평균</span></p>'
    +(gaps.length?'<p class="diff">도감 평균보다 <b>'+gaps.slice(0,2).map(function(g){
        return g[0]+(g[1]>0?'을 강하게':'을 약하게')}).join('</b>, <b>')+'</b> 느끼는 편입니다.</p>'
      :'<p class="diff">도감 평균과 비슷하게 느끼는 편입니다.</p>')
    +(cnt<5?'<p class="diff" style="font-size:11.5px;color:var(--ink3)">기록이 '+cnt+'건이라 아직 경향이라 부르긴 이릅니다.</p>':'')
    +(topTags.length?'<div class="sec"><h3>자주 고른 맛·향</h3><div class="chips">'
      +topTags.map(function(t){var ko=(TAGS.find(function(x){return x[0]===t})||[])[1]||'';
        return '<div class="chip on"><b style="font-family:var(--disp)">'+esc(t)+'</b> <span style="opacity:.7;font-size:10px">'+esc(ko)+' '+tagCnt[t]+'</span></div>'}).join('')
      +'</div></div>':'')
    +(topTemp!==undefined?'<div class="sec"><h3>가장 많이 마신 온도</h3><p class="diff"><b>'
      +TEMPS[topTemp][0]+'</b> '+TEMPS[topTemp][1]+' · '+tempCnt[topTemp]+'회</p></div>':'')
    +(agTot?'<div class="sec"><h3>또 마신다</h3><p class="diff"><b>'+again+'</b> / '+agTot+'건 ('
      +Math.round(again/agTot*100)+'%)</p></div>':'');
}
function noteCount(){return Object.keys(NOTE).reduce(function(a,k){return a+logsOf(k).length},0)}
/* 마지막 백업 이후 얼마나 쌓였나. 백업은 사람이 기억해서 하지 않는다 — 앱이 말해야 한다. */
function sinceBackup(){
  var b=load(K_BACK,null);
  var c=Object.keys(MINE).length, n=noteCount();
  if(!b)return {never:true,cards:c,notes:n};
  return {never:false,at:(b.at||'').slice(0,10),
          cards:Math.max(0,c-(b.cards||0)), notes:Math.max(0,n-(b.notes||0))};
}
var K_VIEW='sake.view.v1';
function saveView(){
  try{save(K_VIEW,{s:($('#sort')||{}).value,m:($('#msort')||{}).value,
                   f:dexFilter,t:dexTaste,mf:mineFilter})}catch(e){}
}
function loadView(){
  var v=load(K_VIEW,null); if(!v)return;
  if(v.s&&$('#sort'))$('#sort').value=v.s;
  if(v.m&&$('#msort'))$('#msort').value=v.m;
  if(v.f)dexFilter=v.f;
  if(typeof v.t==='number')dexTaste=v.t;
  if(v.mf)mineFilter=v.mf;
  $$('[data-dexf]').forEach(function(x){x.classList.toggle('on',x.dataset.dexf===dexFilter)});
  $$('[data-taste]').forEach(function(x){x.classList.toggle('on',+x.dataset.taste===dexTaste)});
  $$('[data-minef]').forEach(function(x){x.classList.toggle('on',x.dataset.minef===mineFilter)});
}
function refresh(){renderHome();renderDex();renderMine();renderStats();renderMe()}

/* ── 시작 ── */
fetch('./catalog.json',{cache:'no-cache'}).then(function(r){return r.json()}).then(function(d){
  CAT=d.items; MINE=load(K_MINE,{}); NOTE=load(K_NOTE,{});
  picLoadAll().then(function(){refresh()});
  fetch('./photos.json',{cache:'no-cache'}).then(function(r){return r.json()})
    .then(function(d){SHOT=d.photos||{};refresh()}).catch(function(){});
  $('#dex-chips').innerHTML=[['all','전체'],['new','안 마신 것'],['mine','담은 것']]
    .map(function(c,i){return '<div class="chip'+(i===0?' on':'')+'" data-dexf="'+c[0]+'">'+c[1]+'</div>'}).join('');
  var tc=$('#dex-taste');
  if(tc)tc.innerHTML='<div class="chip on" data-taste="-1">맛 전체</div>'
    +AX.map(function(a,i){return '<div class="chip" data-taste="'+i+'">'+a[1]+'</div>'}).join('');
  $('#mine-chips').innerHTML=[['all','전체'],['noted','노트 쓴 것'],['blank','아직 안 쓴 것']]
    .map(function(c,i){return '<div class="chip'+(i===0?' on':'')+'" data-minef="'+c[0]+'">'+c[1]+'</div>'}).join('');
  $('#build').textContent='build '+(d.v||1)+' · 도감 '+CAT.length+'종';
  loadView(); refresh();
  var t=null; try{t=localStorage.getItem('sake.tab')}catch(e){}
  go(t&&['home','dex','mine','stat','me'].indexOf(t)>=0?t:'home');
}).catch(function(){ $('#home-recent').innerHTML='<p class="diff">도감을 불러오지 못했습니다.</p>' });

document.addEventListener('click',function(e){
  var nav=e.target.closest('.nav button'); if(nav){go(nav.dataset.go);return}
  var ob=e.target.closest('[data-open-sheet]');
  if(ob){openSheet(ob.dataset.openSheet);return}
  var c=e.target.closest('.c');
  if(c){c.classList.toggle('flip');return}
  var tf=e.target.closest('[data-taste]');
  if(tf){dexTaste=+tf.dataset.taste;
    $$('[data-taste]').forEach(function(x){x.classList.toggle('on',x===tf)});
    dexN=60;renderDex();saveView();return}
  var df=e.target.closest('[data-dexf]');
  if(df){dexFilter=df.dataset.dexf;$$('[data-dexf]').forEach(function(x){x.classList.toggle('on',x===df)});
    dexN=60;renderDex();saveView();return}
  var mf=e.target.closest('[data-minef]');
  if(mf){mineFilter=mf.dataset.minef;$$('[data-minef]').forEach(function(x){x.classList.toggle('on',x===mf)});
    renderMine();saveView();return}
  if(e.target.id==='dex-more'){dexN+=60;renderDex();return}
  if(e.target.id==='a-manual'){openManual();return}
  if(e.target.id==='go-blank'){var b=nextBlank(null); if(b)openSheet(b); return}
  if(e.target.id==='tl-more'){var x=$('#me-line');x.dataset.all='1';renderTimeline();return}
  if(e.target.id==='go-backup'){go('me');setTimeout(function(){var x=$('#exp');if(x)x.click()},220);return}
  var ar=e.target.closest('[data-area]');
  if(ar){go('dex');var q=$('#q');q.value=ar.dataset.area;
    q.dispatchEvent(new Event('input',{bubbles:true}));return}
  if(e.target.id==='sheet'){closeSheet();return}
});
document.addEventListener('input',function(e){
  if(e.target.id==='q'){dexN=60;renderDex()}
  if(e.target.id==='mq')renderMine();
});
document.addEventListener('change',function(e){
  if(e.target.id==='sort'){renderDex();saveView()}
  if(e.target.id==='msort'){renderMine();saveView()}
});
document.addEventListener('keydown',function(e){if(e.key==='Escape')closeSheet()});

/* 내보내기 · 가져오기 */
document.addEventListener('click',function(e){
  if(e.target.id==='exp'){
    var blob=new Blob([JSON.stringify({v:1,exported_at:new Date().toISOString(),
      mine:MINE,notes:NOTE},null,1)],{type:'application/json'});
    var a=document.createElement('a');a.href=URL.createObjectURL(blob);
    a.download='sake_my_record.json';a.click();
    /* 언제·어디까지 백업했는지 남긴다 — 그래야 그 뒤로 얼마나 쌓였는지 셀 수 있다 */
    save(K_BACK,{at:new Date().toISOString(),cards:Object.keys(MINE).length,notes:noteCount()});
    renderMe(); renderHome(); toast('내보냈습니다');
  }
  if(e.target.id==='imp')$('#file').click();
});
document.addEventListener('change',function(e){
  if(e.target.id==='picfile'&&e.target.files[0]){
    var id=e.target.dataset.for, f=e.target.files[0];
    if(!/^image\//.test(f.type)){toast('이미지 파일만 됩니다');return}
    var first=!cutSession;
    toast(first?'처음 한 번만 준비합니다 — 20초쯤 걸려요':'배경을 지우는 중…');
    var tick=first?setInterval(function(){toast('배경 지우기를 준비하는 중…')},3000):null;
    shrink(f,true).then(function(url){return picPut(id,url)}).then(function(){
      if(tick)clearInterval(tick);
      toast('사진을 넣었습니다'); refresh(); openSheet(id);
    }).catch(function(){if(tick)clearInterval(tick);toast('사진을 읽지 못했습니다')});
    return;
  }
  if(e.target.id!=='file'||!e.target.files[0])return;
  var fr=new FileReader();
  fr.onload=function(){
    try{
      var d=JSON.parse(fr.result);
      /* 카드는 합집합. 같은 병이 양쪽에 있으면 먼저 담은 날을 남긴다. */
      var added=0;
      if(d.mine)Object.keys(d.mine).forEach(function(k){
        var old=MINE[k], v=d.mine[k];
        if(!old){MINE[k]=v;added++;return}
        if(v.at&&(!old.at||v.at<old.at))old.at=v.at;
        if(!old.name&&v.name)old.name=v.name;
      });
      /* 노트는 **합친다**. 통째로 바꾸면 이쪽 기기에서 쓴 기록이 날아간다
         — 폰과 PC 를 오가며 쓰면 그대로 유실이었다(2026-09-16).
         같은 시각·같은 메모면 같은 기록으로 보고 하나만 남긴다. */
      var noteAdded=0;
      if(d.notes)Object.keys(d.notes).forEach(function(k){
        var incoming=d.notes[k]; if(!Array.isArray(incoming))incoming=[incoming];
        var cur=logsOf(k).slice(), seen={};
        cur.forEach(function(l){seen[(l.at||'')+'|'+(l.memo||'')]=1});
        incoming.forEach(function(l){
          if(!l)return;
          var sig=(l.at||'')+'|'+(l.memo||'');
          if(seen[sig])return;
          seen[sig]=1; cur.push(l); noteAdded++;
        });
        cur.sort(function(x,y){return (x.at||'').localeCompare(y.at||'')});
        NOTE[k]=cur;
      });
      /* 내보낸 컬렉션 파일(items 배열) 도 받는다.
         brand 가 빈 항목은 도감에 없는 술이다 — 버리지 않고 own: id 로 담는다
         (2026-09-16: 135종 중 9종이 이렇게 통째로 유실되고 있었다). */
      if(d.items){
        d.items.forEach(function(it){
          var prod=(it.name||'').trim(), jp=(it.jp||'').trim(), key;
          if(it.brand){
            key=prod?it.brand+'#'+prod:it.brand;
          }else{
            /* 도감에 없는 술. jp 가 비어 제품명만 오는 경우가 있어(실측 8건)
               괄호 앞 토막을 이름으로 세운다. */
            var label=jp||prod; if(!label)return;
            if(!jp)jp=prod.split(/[ (（·]/)[0].trim()||prod;
            key='own:'+label.replace(/[^\w가-힣ぁ-んァ-ン一-龯]/g,'').slice(0,24);
            if(prod&&prod!==jp)key+='#'+prod;
          }
          /* 같은 병이 두 번 오면 먼저 마신 날짜를 남긴다 */
          var at=it.at||'', old=MINE[key];
          if(old&&old.at&&(!at||old.at<at))at=old.at;
          MINE[key]={at:at,jp:jp||'?',name:prod};
        });
      }
      /* 사진 묶음 — 카드마다 손으로 넣으면 수십 번을 눌러야 한다. 통째로 받는다. */
      var picN=0;
      if(d.photos){
        var jobs=Object.keys(d.photos).map(function(k){picN++;return picPut(k,d.photos[k])});
        Promise.all(jobs).then(function(){refresh();
          toast('사진 '+picN+'장을 넣었습니다')});
      }
      save(K_MINE,MINE);save(K_NOTE,NOTE);refresh();
      if(!picN)toast('가져왔습니다 — 카드 '+Object.keys(MINE).length+'종'
        +(added||noteAdded?' (새로 '+added+'장·노트 '+noteAdded+'건)':' (새로 들어온 것 없음)'));
    }catch(err){toast('파일을 읽지 못했습니다')}
  };
  fr.readAsText(e.target.files[0]);
});
if('serviceWorker' in navigator)navigator.serviceWorker.register('./sw.js').catch(function(){});

/* 설치 안내 — 아직 홈 화면에 추가하지 않은 경우에만. 한 번 닫으면 다시 뜨지 않는다.
   아이폰 사파리는 설치 API 가 없어 손으로 하는 법을 적고, 안드로이드 크롬은
   beforeinstallprompt 를 잡아 버튼 한 번으로 끝낸다(안내만 띄우면 아무도 안 한다). */
(function(){
  var iOS=/iPad|iPhone|iPod/.test(navigator.userAgent)&&!window.MSStream;
  var standalone=window.navigator.standalone===true||
    (window.matchMedia&&window.matchMedia('(display-mode: standalone)').matches);
  var dismissed=false; try{dismissed=localStorage.getItem('sake.install.hide')==='1'}catch(e){}
  var box=document.getElementById('install'), deferred=null;
  function show(){if(box&&!standalone&&!dismissed)box.hidden=false}
  if(iOS)show();
  window.addEventListener('beforeinstallprompt',function(e){
    e.preventDefault(); deferred=e;
    var how=document.getElementById('i-how'), add=document.getElementById('i-add');
    if(how)how.textContent='버튼 한 번이면 끝납니다. 주소창 없이 전체화면으로 뜨고, 비행기에서도 열립니다.';
    if(add)add.hidden=false;
    show();
  });
  window.addEventListener('appinstalled',function(){
    if(box)box.hidden=true;
    try{localStorage.setItem('sake.install.hide','1')}catch(err){}
  });
  document.addEventListener('click',function(e){
    if(e.target.id==='i-add'&&deferred){
      deferred.prompt(); deferred=null;
      if(box)box.hidden=true;
      return;
    }
    if(e.target.id==='i-close'){
      if(box)box.hidden=true;
      try{localStorage.setItem('sake.install.hide','1')}catch(err){}
    }
  });
})();
})();
